function allNotices(){return visibleHistory(data.notices).filter(n=>{const id=n.name?.split(' · ')[0]||'';if(id.startsWith('BL-'))return canPage('bills')||canPage('payments');if(id.startsWith('AT-'))return canPage('attendance');if(id.startsWith('REQ-'))return canPage('demands');return true;});}
function unreadNotices(){return allNotices().filter(n=>!readIds().includes(n.id));}
