function schedule(){let people=visibleRows(catalog.workers()).slice(0,8);return heading('排班管理','2026.09.14 — 09.20 · 按仓库当地时间 · 点击班次查看或调整',btn('导出排班','export','export'))+stats([['已安排人员',people.length,'当前展示人员','people'],['计划班次',people.length*5,'每人每周 5 班','calendar'],['班次时长','8 h','休息时间按规则扣除','clock'],['冲突待处理','0','同一人员不重叠安排','shield']])+`<div class="card"><div class="card-head"><h3>周排班 · 华沙仓 / 分拣组</h3><span class="small">${IS?'供应商提交安排，企业确认实际班次':'实际执行安排 · 组长 / 文员 / 仓长可调整'}</span></div><div class="tablewrap"><table class="calendar"><thead><tr><th>人员 / 工种</th>${['周一 09/14','周二 09/15','周三 09/16','周四 09/17','周五 09/18','周六 09/19','周日 09/20'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${people.map((r,i)=>`<tr><td><b>${r.name}</b><div class="sub">${r.id} · ${r.job}</div></td>${Array.from({length:7},(_,j)=>`<td>${j>4?'<div class="rest">休息</div>':`<div class="shift" tabindex="0" role="button" data-shift="${r.id}|${j}">${(data.custom.shifts||{})[r.id+'|'+j]||'09:00–18:00'}<br>分拣组 · 8 h</div>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function analytics(){return heading('经营分析','当前授权范围 · 2026 年 9 月 · 示例统计，不与流程演示小样本混算',btn('导出报告','export','export'))+stats([['需求满足率','94.8%','试工通过人数 / 需求人数','people'],['30 日留存率','87.6%','成熟入场批次 · 已满 30 日','chart'],['对账差错率','0.42%','错误明细 / 首次提交明细','shield'],['平均对账耗时','1.8 天','工作日统计 · 非确认截止','clock']])+`<div class="dashboard-grid"><div class="card"><div class="card-head"><h3>用工需求与试工通过</h3><span class="small">周趋势</span></div><div class="chart">${[67,79,91,84,94,89,98].map((h,i)=>`<div class="chart-col"><i class="light" style="height:${h}%"></i><i style="height:${h-7}%"></i><span>W${i+33}</span></div>`).join('')}</div><div class="chart-legend">需求人数 / 试工通过人数 · 同一需求集合</div></div><div class="card"><div class="card-head"><h3>原币成本</h3><span class="small">不直接跨币种相加</span></div>${curr.slice(0,5).map((c,i)=>`<div class="rank"><span>${i+1}</span><span>${c}</span><span>${(128000+i*31200).toLocaleString()}</span><span class="small">原币</span></div>`).join('')}</div></div><div class="card" style="margin-top:18px"><div class="card-head"><h3>仓库履约明细</h3></div><table><thead><tr><th>仓库</th><th>需求人数</th><th>分配人数</th><th>试工通过</th><th>满足率</th><th>缺口</th></tr></thead><tbody>${locations.slice(0,4).map((w,i)=>`<tr><td>${w}</td><td>${100+i*20}</td><td>${100+i*20}</td><td>${95+i*18}</td><td>${((95+i*18)/(100+i*20)*100).toFixed(2)}%</td><td>${5+i*2}</td></tr>`).join('')}</tbody></table></div>`}
function toast(s){document.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=s;document.body.append(e);translate();setTimeout(()=>e.remove(),3500)}
function closeLayer(){document.getElementById('layers').innerHTML='';layerTrigger?.focus?.();}
function overlay(title,subtitle,body,foot=''){layerTrigger=document.activeElement;document.getElementById('layers').innerHTML=`<div class="overlay"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-head"><div><h2>${title}</h2><span class="small">${subtitle}</span></div><button class="plain" data-act="close">${ic('close')}关闭</button></div><div class="drawer-body">${body}</div>${foot?`<div class="drawer-foot">${foot}</div>`:''}</section></div>`;bindLayers();document.querySelector('.drawer button')?.focus();translate()}
function ask(title,text,callback){layerTrigger=document.activeElement;const root=document.createElement('div');root.className='modal-back';root.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><h2>${title}</h2><p>${text}</p><div class="actions">${btn('取消','cancel-modal','close')}${btn('确认','ok-modal','check',true)}</div></section>`;document.body.append(root);root.querySelector('[data-act=cancel-modal]').onclick=()=>{root.remove();layerTrigger?.focus()};root.querySelector('[data-act=ok-modal]').onclick=()=>{root.remove();callback()};root.querySelector('button').focus();translate()}
function findRow(id){return getRows(page).find(r=>r.id===id)}
function detail(id){const r=findRow(id);if(!r)return;let act=permittedAction(page,r),fields=Object.entries(r).filter(([k])=>!['reason','name','id'].includes(k));let labels={code:'工号',warehouse:'仓库',supplier:'供应商',date:'业务日期',shift:'班次',clock:'核对后打卡',rawClock:'原始打卡',hours:'确认工时',status:'当前状态',owner:'责任人',period:'结算周期',dates:'结算期间',currency:'币种',amount:'应付金额',paid:'已付金额',invoice:'发票编号',request:'报账编号',count:'需求人数',assigned:'已安排人数',job:'工种',phone:'联系电话',detail:'说明',contact:'对接人',unit:'计价单位',entity:'结算企业',zone:'时区',used:'使用率',anchor:'周期锚点',precision:'金额精度',bank:'开户银行',rawClock:'原始打卡'};
let body=`${badge(r.status)}<div class="detail-grid">${fields.map(([k,v])=>`<div><label>${labels[k]||k}</label><b>${esc(['amount','paid'].includes(k)?money(v,r.currency):v)}</b></div>`).join('')}</div>`;
if(['attendance','disputes','clock'].includes(page)){body+=`<div class="section-title">工时依据</div><div class="notice ${r.reason?'warn':''}">${ic('info')}${r.reason||'原始打卡 → 实际班次 → 休息扣除 → 有效工时'}</div><table><thead><tr><th>班次跨度</th><th>休息扣除</th><th>有效工时</th><th>适用规则</th></tr></thead><tbody><tr><td>${r.shift.startsWith('22')?'8':'9'} h</td><td>${r.shift.startsWith('22')?'0':'1'} h</td><td>${r.hours} h</td><td>当地标准班次 · V2</td></tr></tbody></table><p class="small">内部确认：组长／文员 → 供应商复核。无固定截止时间。</p>`;}
if(['bills','invoices','payments'].includes(page)){body+=`<div class="section-title">费用核对</div><table><thead><tr><th>费用项</th><th>数量</th><th>含税单价</th><th>金额</th></tr></thead><tbody><tr><td>已确认普通工时</td><td>${r.hours} h</td><td>${money(r.amount/r.hours,r.currency)}</td><td>${money(r.amount,r.currency)}</td></tr></tbody></table><div class="notice" style="margin-top:14px">${ic('shield')}原币账单 · 工时已双确认 · 未付 ${money(r.amount-r.paid,r.currency)}</div><div class="section-title">处理进度</div><div class="timeline"><div>工时已由内部和供应商确认<div class="small">依据锁定，变更需要重新确认</div></div><div>${r.status==='待 HR 确认'?'请 HR 核对并确认账单':'HR 已确认账单'}<div class="small">${r.id}</div></div><div>${r.invoice?'发票已提交 · '+esc(r.invoice):'供应商复核后提交发票'}<div class="small">${r.request?'报账 '+r.request:'条件满足后自动发起报账'}</div></div><div>${['部分付款','已付款','审批中'].includes(r.status)?r.status:'等待下一责任人处理'}<div class="small">财务进度只读，内部操作不能直接标记已付款</div></div></div>`;}
const logs=data.logs.filter(l=>l.name===r.id);body+=`<div class="section-title">处理记录</div><div class="timeline">${logs.map(l=>`<div>${esc(l.action)} · ${esc(l.status)}<div class="small">${l.owner} · ${l.time}</div></div>`).join('')||'<div>业务已登记<div class="small">2026-09-13 · 演示记录</div></div>'}</div>`;
let foot=btn('关闭','close','close');if(IS&&((page==='attendance'&&r.status==='待供应商复核')||(page==='bills'&&r.status==='待供应商复核')))foot+=`<button data-row-action="dispute|${r.id}">${ic('info')}提出异议</button>`;if(act)foot+=`<button class="primary" data-row-action="${act[1]}|${r.id}">${ic('check')}${act[0]}</button>`;overlay(r.name||r.id,r.id,body,foot)}
function mutateRecord(k,r,patch){let core=['attendance','disputes','clock'].includes(k)?'attendance':['bills','invoices','payments'].includes(k)?'bills':k==='demands'?'demands':null;if(core){Object.assign(data[core].find(x=>x.id===r.id),patch)}else{const customRow=(Array.isArray(data.custom[k])?data.custom[k]:[]).find(x=>x.id===r.id);if(customRow)Object.assign(customRow,patch);data.custom.overrides=data.custom.overrides||{};data.custom.overrides[r.id]={...(data.custom.overrides[r.id]||{}),...patch}}}
const baseGetRows=getRows;getRows=function(k){return baseGetRows(k).map(r=>({...r,...(data.custom.overrides||{})[r.id]}))};
function execute(action,r){if(!r)return;if(action==='confirm-assign'){mutateRecord('demands',r,{status:'已安排'});log('企业确认安排',r.id,'已安排');closeLayer();render();toast('实际安排已确认');return}if(action==='confirm-att'){const eligible=permittedAction('attendance',r);if(!eligible||eligible[1]!==action)return toast('请先完成前置确认或处理异常');const status=IS?'双方已确认':'待供应商复核';mutateRecord('attendance',r,{status});log(IS?'供应商确认工时':'内部确认考勤',r.id,status);if(IS){let group=data.attendance.filter(x=>x.supplier==='Atlas Staffing'&&x.warehouse===r.warehouse&&x.status==='双方已确认'&&!x.billed);if(group.length){let c=curr[locations.indexOf(r.warehouse)],hours=group.reduce((a,x)=>a+x.hours,0);let bill={id:'BL-AUTO-'+Date.now().toString().slice(-7)+'-'+data.bills.length,name:'Atlas Staffing · '+r.warehouse,supplier:'Atlas Staffing',warehouse:r.warehouse,period:'双周',dates:'09-07 ～ 09-20',currency:c,amount:hours*[120,18,20,300][locations.indexOf(r.warehouse)],hours,status:'待 HR 确认',paid:0};data.bills.push(bill);group.forEach(x=>x.billed=bill.id);log('系统生成账单',bill.id,'待 HR 确认')}}save();closeLayer();selected.clear();render();toast(IS?'工时已确认，已自动生成待 HR 确认账单':'考勤已确认，已交供应商复核');return}
if(action==='confirm-bill'){const a=permittedAction('bills',r);if(!a||a[1]!==action)return toast('当前状态不可确认');const status=IS?'待上传发票':'待供应商复核';mutateRecord('bills',r,{status});log(IS?'供应商复核账单':'HR 确认账单',r.id,status);closeLayer();render();toast('账单已确认 · '+status);return}
if(['correct-att','invoice','dispute','dispatch','assign'].includes(action)){actionForm(action,r);return}
if(action==='edit-record'){specialForm(r);return}
if(action==='toggle-account'){ask('变更账户状态','停用后该账户将无法继续处理业务，历史记录仍然保留。',()=>{let st=r.status==='已停用'?'已启用':'已停用';mutateRecord(page,r,{status:st});log('变更账户状态',r.id,st);closeLayer();render();toast(st)});return}
if(action==='verify'){overlay('核验与处理',r.id,`<div class="notice">${ic('info')}请核对业务依据后记录结论。</div><form id="verify-form"><div class="form-grid"><label class="full">核验说明<textarea id="verification" required placeholder="请输入已核对的资料及结论"></textarea></label></div><div class="error" id="form-error"></div></form>`,btn('取消','close','close')+btn('核验通过','verify-save','check',true));document.querySelector('[data-act=verify-save]').onclick=()=>{let v=document.getElementById('verification').value.trim();if(!v){document.getElementById('form-error').textContent='请填写核验说明';return}let st=page==='access'?'已生效':page==='integrations'?'运行正常':'已通过';mutateRecord(page,r,{status:st});log('核验通过',r.id,st);closeLayer();render();toast('核验结果已保存')};return}}
function actionForm(action,r){let title={'correct-att':'修正考勤','invoice':'提交发票','dispute':'提出异议','dispatch':'分发用工需求','assign':'安排需求人员'}[action];let fields='';if(action==='invoice')fields=`<label>发票编号<input id="invoice-id" placeholder="例如 INV-2026-001" required></label><label>发票币种<select id="invoice-currency">${curr.map(c=>`<option ${r.currency===c?'selected':''}>${c}</option>`).join('')}</select></label><label>含税金额<input id="invoice-amount" type="number" value="${r.amount}" min="0"></label><label>受票主体<input value="${r.warehouse.includes('东京')?'HRONE APAC':'HRONE Europe'}" readonly></label><label class="full">发票文件<input id="invoice-file" type="file" accept=".pdf,.png,.jpg,.jpeg"></label><label class="full"><span><input id="invoice-sample" type="checkbox"> 使用演示发票（无需上传真实资料）</span></label>`;
if(action==='correct-att')fields=`<label>确认工时<input type="number" id="hours" min="0" max="24" step="0.25" value="8"></label><label>补充下班打卡<input id="clock-end" type="time" value="18:00"></label><label class="full">修正依据<textarea id="reason" required placeholder="说明补卡依据或差异原因"></textarea></label>`;
if(action==='dispute')fields=`<label class="full">异议说明<textarea id="reason" placeholder="请注明工时或金额差异及核对依据"></textarea></label>`;
if(action==='dispatch'||action==='assign')fields=`<label>供应商<input value="Atlas Staffing" readonly></label><label>${action==='dispatch'?'分配人数':'安排人数'}<input id="count" type="number" min="1" max="${r.count}" value="${r.count}"></label><label class="full">安排说明<textarea id="reason" placeholder="请补充班次或到岗安排">${r.shift} · ${r.job}</textarea></label>`;
overlay(title,r.id,`<div class="notice">${ic('info')}${action==='invoice'?'账单已双确认；核对主体、币种、金额及重复发票，满足条件后自动发起报账。':action==='correct-att'?'保存后回到待内部确认，原供应商确认不再有效。':'请核对当前内容，处理结果将同步到下一责任方。'}</div><form id="action-form"><div class="form-grid">${fields}</div><div class="error" id="form-error" role="alert"></div></form>`,btn('取消','close','close')+btn(action==='invoice'?'提交并发起报账':'保存并继续','action-save','check',true));
document.querySelector('[data-act=action-save]').onclick=()=>{const err=s=>document.getElementById('form-error').textContent=s;let result;
if(action==='invoice'){let id=document.getElementById('invoice-id').value.trim(),c=document.getElementById('invoice-currency').value,a=Number(document.getElementById('invoice-amount').value),file=document.getElementById('invoice-file').files[0],sample=document.getElementById('invoice-sample').checked;if(!id)return err('请填写发票编号');if(c!==r.currency)return err('发票币种与账单不一致，请核对');if(a!==r.amount)return err('本账单演示采用整单开票，发票金额必须等于 '+money(r.amount,r.currency));if(!file&&!sample)return err('请上传发票或选择演示发票');if(data.invoices.includes(id)||data.bills.some(b=>b.invoice===id))return err('该发票已提交，不能重复占用费用');if(data.bills.find(b=>b.id===r.id).request)return err('此账单已发起报账，不能重复提交');data.invoices.push(id);result='审批中';mutateRecord('bills',r,{status:result,invoice:id,request:'EXP-202609-'+String(Date.now()).slice(-5)});log('供应商提交发票',r.id,'发票核验通过');log('系统自动发起报账',r.id,result)}
if(action==='correct-att'){let h=Number(document.getElementById('hours').value),reason=document.getElementById('reason').value.trim();if(!reason)return err('请填写修正依据');if(!Number.isFinite(h)||h<0||h>24)return err('工时须在 0–24 小时之间');mutateRecord('attendance',r,{rawClock:r.rawClock||r.clock,hours:h,status:'待内部确认',reason:'已修正：'+reason,clock:'09:00 / '+document.getElementById('clock-end').value});result='待内部确认';log('修正考勤',r.id,result)}
if(action==='dispute'){let reason=document.getElementById('reason').value.trim();if(!reason)return err('请填写具体异议');result=page==='attendance'?'争议待处理':'待 HR 确认';mutateRecord(page,r,{status:result,reason});log('供应商提出异议',r.id,result)}
if(action==='dispatch'||action==='assign'){let n=Number(document.getElementById('count').value);if(!Number.isInteger(n)||n<1||n>r.count)return err('人数须为 1–'+r.count+' 的整数');result=action==='dispatch'?'待供应商安排':'待企业确认';mutateRecord('demands',r,{status:result,assigned:n});log(title,r.id,result)}save();closeLayer();render();toast(action==='invoice'?'发票已核对，内部报账已自动发起':'已保存 · '+result)};}
function createForm(){if(specialFields[page])return specialForm();const isDemand=page==='demands';overlay(isDemand?'提出用工需求':'新增'+conf[page][0],'新增业务记录',`<form><div class="form-grid"><label class="full">${isDemand?'需求名称':'名称'}<input id="new-name" required placeholder="请输入"></label><label>仓库<select id="new-warehouse">${locations.map(w=>`<option>${w}</option>`).join('')}</select></label><label>供应商<input id="new-supplier" value="Atlas Staffing" ${IS?'readonly':''}></label>${isDemand?'<label>工种<input id="new-job" value="分拣员"></label><label>需求人数<input id="new-count" type="number" min="1" value="20"></label><label>用工日期<input id="new-date" type="date" value="2026-09-21"></label><label>班次<input id="new-shift" value="09:00–18:00"></label>':'<label>生效日期<input id="new-date" type="date" value="2026-09-13"></label><label>业务说明<input id="new-detail" placeholder="填写适用范围或说明"></label>'}<label class="full">备注<textarea id="new-note" placeholder="补充业务说明"></textarea></label></div><div class="error" id="form-error"></div></form>`,btn('取消','close','close')+btn('提交','create-save','check',true));document.querySelector('[data-act=create-save]').onclick=()=>{let name=document.getElementById('new-name').value.trim();if(!name){document.getElementById('form-error').textContent='请填写名称';return}let r={id:(isDemand?'REQ-':'NEW-')+Date.now().toString().slice(-7),name,warehouse:document.getElementById('new-warehouse').value,supplier:document.getElementById('new-supplier').value,date:document.getElementById('new-date').value,status:isDemand?'待 HR 分发':'待审核',owner:role};if(isDemand){r.count=Number(document.getElementById('new-count').value);if(!Number.isInteger(r.count)||r.count<=0){document.getElementById('form-error').textContent='人数须为正整数';return}r.job=document.getElementById('new-job').value;r.shift=document.getElementById('new-shift').value;r.assigned=0;data.demands.unshift(r)}else{r.detail=document.getElementById('new-detail').value;(data.custom[page]??=[]).unshift(r)}log('提交'+conf[page][0],r.id,r.status);closeLayer();filters={};render();toast('已提交，记录已加入列表')};}
function exportDialog(){overlay('导出与字段设置','仅导出当前筛选及授权范围',`<p class="small">选择需要的字段，生成可下载的 CSV 文件。</p><div class="form-grid">${tableCols(page).map(([k,l])=>`<label><span><input type="checkbox" name="export-field" value="${k}" checked> ${l}</span></label>`).join('')}</div>`,btn('取消','close','close')+btn('下载 CSV','download','export',true));document.querySelector('[data-act=download]').onclick=()=>{let cols=[...document.querySelectorAll('[name=export-field]:checked')].map(x=>x.value);if(!cols.length)return toast('请至少选择一个字段');let rs=['dashboard','analytics','schedule'].includes(page)?visibleRows(catalog.workers()):rowsFiltered();const safe=x=>'"'+String(x??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';let text='\ufeff'+[cols,...rs.map(r=>cols.map(c=>r[c]??''))].map(a=>a.map(safe).join(',')).join('\n');let url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=conf[page][0]+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeLayer();toast('导出已生成')};}
function menu(){layerTrigger=document.activeElement;document.getElementById('layers').innerHTML=`<div class="menu-panel" role="dialog" aria-label="全部菜单"><div style="display:flex;justify-content:space-between;margin-bottom:22px"><b>全部菜单</b><button class="plain" data-act="close">${ic('close')}关闭</button></div><div class="menu-grid">${[...new Set(rights[role].map(k=>conf[k][2]))].map(d=>`<div><h3>${d}</h3>${rights[role].filter(k=>conf[k][2]===d).map(k=>`<button data-page="${k}">${ic(conf[k][1])}${conf[k][0]}</button>`).join('')}</div>`).join('')}</div></div>`;bindLayers();document.querySelector('.menu-panel button').focus();translate()}
function profile(){overlay('用户会话',IS?'Julia Nowak · Atlas Staffing':'林悦 · HRONE',`<div class="notice">${ic('info')}评审身份切换仅用于查看不同角色的任务和权限。</div><div class="section-title">当前角色</div><div class="chips"><span>${role}</span><span>${IS?'本供应商合作范围':'角色授权范围'}</span></div><div class="section-title">切换评审身份</div><div class="form-grid">${roles.map(r=>`<button data-role="${r}">${ic('people')}${r}</button>`).join('')}</div><div class="section-title">账户</div><p class="small">${IS?'julia.nowak@atlas.example':'lin.yue@hrone.example'} · 演示会话</p><a href="journey.html">返回整体旅程导航 ↗</a>`,btn('退出登录','logout','back'));}
function notices(){openMessages('notifications');}
function bindLayers(){bind(document.getElementById('layers'))}
function bind(root=document.getElementById('app')){root.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>route(e.dataset.page));root.querySelectorAll('[data-domain]').forEach(e=>e.onclick=()=>route(rights[role].find(k=>conf[k][2]===e.dataset.domain)));root.querySelectorAll('[data-close-tab]').forEach(e=>e.onclick=()=>{const k=e.dataset.closeTab,idx=tabs.indexOf(k);tabs=tabs.filter(t=>t!==k);if(page===k)page=tabs[Math.max(0,idx-1)]||'dashboard';render()});root.querySelectorAll('[data-detail]').forEach(e=>e.onclick=()=>detail(e.dataset.detail));root.querySelectorAll('[data-row-action]').forEach(e=>e.onclick=()=>{let [a,id]=e.dataset.rowAction.split('|');execute(a,findRow(id))});root.querySelectorAll('[data-task]').forEach(e=>e.onclick=()=>{let [k,id]=e.dataset.task.split('|');route(k);detail(id)});root.querySelectorAll('[data-status]').forEach(e=>e.onclick=()=>{filters.status=e.dataset.status;pageNo=1;selected.clear();render()});root.querySelectorAll('[data-period]').forEach(e=>e.onclick=()=>{filters.period=e.dataset.period;pageNo=1;render()});root.querySelectorAll('[data-select]').forEach(e=>e.onchange=()=>{e.checked?selected.add(e.dataset.select):selected.delete(e.dataset.select);render()});root.querySelectorAll('[data-role]').forEach(e=>e.onclick=()=>{role=e.dataset.role;sessionStorage.setItem('role-'+SYS,role);tabs=['dashboard'];route('dashboard')});root.querySelectorAll('[data-message-tab]').forEach(e=>e.onclick=()=>{messageTab=e.dataset.messageTab;messageFilter=messageTab==='tasks'?'pending':'all';render()});root.querySelectorAll('[data-message-filter]').forEach(e=>e.onclick=()=>{messageFilter=e.dataset.messageFilter;render()});root.querySelectorAll('[data-message-read]').forEach(e=>e.onclick=()=>{let ids=readIds(),id=e.dataset.messageRead,i=ids.indexOf(id);i<0?ids.push(id):ids.splice(i,1);save();render()});root.querySelectorAll('[data-shift]').forEach(e=>{e.onclick=()=>shiftForm(e.dataset.shift);e.onkeydown=x=>{if(x.key==='Enter')e.click()}});root.querySelectorAll('[data-act]').forEach(e=>e.onclick=()=>action(e.dataset.act));let q=root.querySelector('#q');if(q)q.onkeydown=e=>{if(e.key==='Enter')action('search')};let gs=root.querySelector('#global-search');if(gs)gs.onkeydown=e=>{if(e.key==='Enter'){let k=rights[role].find(k=>conf[k][0].includes(gs.value));k?route(k):toast('未找到有权限访问的页面')}};let all=root.querySelector('#select-all');if(all)all.onchange=()=>{rowsFiltered().slice((pageNo-1)*10,pageNo*10).forEach(r=>all.checked?selected.add(r.id):selected.delete(r.id));render()};}
function shiftForm(key){let [id,j]=key.split('|');const editable=IS||['组长','文员','仓长'].includes(role);overlay('班次安排',id+' · 2026-09-'+(14+Number(j)),`<div class="form-grid"><label>开始时间<input id="shift-start" type="time" value="09:00" ${editable?'':'readonly'}></label><label>结束时间<input id="shift-end" type="time" value="18:00" ${editable?'':'readonly'}></label><label class="full">调整原因<textarea id="shift-reason" ${editable?'':'readonly'} placeholder="说明现场调整或替班原因"></textarea></label></div><div class="error" id="form-error"></div>`,btn('关闭','close','close')+(editable?btn('保存班次','shift-save','check',true):''));if(editable)document.querySelector('[data-act=shift-save]').onclick=()=>{if(!document.getElementById('shift-reason').value.trim()){document.getElementById('form-error').textContent='请填写调整原因';return}let a=document.getElementById('shift-start').value,b=document.getElementById('shift-end').value;if(a===b){document.getElementById('form-error').textContent='起止时间不能相同';return}data.custom.shifts??={};data.custom.shifts[key]=a+'–'+b;log('调整班次',id,IS?'待企业确认':'已更新实际安排');closeLayer();render();toast('班次安排已保存')};}
function action(a){if(a==='home')return route('dashboard');if(a==='tasks'||a==='messages')return openMessages('tasks');if(a==='read-all'){for(const n of unreadNotices())readIds().push(n.id);save();render();toast('通知已全部标为已读');return}if(a==='menu')return menu();if(a==='close')return closeLayer();if(a==='profile')return profile();if(a==='notices')return notices();if(a==='create')return createForm();if(a==='export')return exportDialog();if(a==='advanced'){advanced=!advanced;render();return}if(a==='search'){filters.q=document.getElementById('q')?.value||'';filters.warehouse=document.getElementById('warehouse')?.value||'';filters.currency=document.getElementById('currency')?.value||'';filters.date=document.getElementById('datefilter')?.value||'';pageNo=1;render();return}if(a==='reset'){filters={};selected.clear();pageNo=1;render();return}if(a==='prev'){pageNo=Math.max(1,pageNo-1);render();return}if(a==='next'){pageNo++;render();return}if(a==='clear-select'){selected.clear();render();return}if(a==='batch'){let eligible=rowsFiltered().filter(r=>selected.has(r.id)&&['confirm-att','confirm-bill'].includes(permittedAction(page,r)?.[1]));if(!eligible.length)return toast('所选记录无可确认项，请检查角色、状态或异常');ask('批量确认',`共 ${eligible.length} 条满足确认条件；其他记录保留原状态。`,()=>eligible.forEach(r=>execute(permittedAction(page,r)[1],r)));return}if(a==='logout'){ask('退出当前会话？','退出后将清除当前身份的受保护页面。',()=>{sessionStorage.removeItem('session-'+SYS);closeLayer();login()});return}if(a==='language'){overlay('语言 / Language','即时切换并保留页面与筛选',`<div class="segmented"><button data-language="zh">简体中文</button><button data-language="en">English</button></div>`,btn('关闭','close','close'));document.querySelectorAll('[data-language]').forEach(e=>e.onclick=()=>{lang=e.dataset.language;sessionStorage.setItem('lang-'+SYS,lang);closeLayer();render()});return}}
function login(){closeLayer();document.getElementById('app').innerHTML=`<div class="login"><div class="login-hero">${systemBrand()}<div><span class="small">GLOBAL WORKFORCE, CONNECTED.</span><h1>让用工协同<br>清晰、有序。</h1><p>连接企业、仓库与供应商。<br>从每一次人员安排，到每一笔费用确认。</p></div><span class="small">HRONE · 全球劳务协同</span></div><div class="login-box"><span class="small">统一身份认证 · 演示登录</span><h2>${IS?'LABOR DISPATCHING':'OTWS'}</h2><p class="small">使用演示身份进入业务评审，无需真实账户。</p><label for="login-name">工号 / 账户</label><input id="login-name" value="${IS?'julia.nowak':'lin.yue'}"><label for="login-pw">密码</label><input id="login-pw" type="password" value="demo2026"><label for="login-role">评审角色</label><select id="login-role">${roles.map(r=>`<option>${r}</option>`).join('')}</select><div id="login-error" class="error"></div>${btn('登录','login','arrow',true)}<div style="display:flex;justify-content:space-between">${btn('修改密码','password','shield')}${btn('二维码登录','qr','grid')}</div><button class="plain" data-act="language">${ic('globe')}中文 / English</button><a href="journey.html" style="float:right;padding-top:10px">返回旅程导航</a></div></div>`;bind();document.querySelector('[data-act=login]').onclick=()=>{if(!document.getElementById('login-name').value||!document.getElementById('login-pw').value){document.getElementById('login-error').textContent='请填写账户和密码';return}role=document.getElementById('login-role').value;sessionStorage.setItem('session-'+SYS,'demo');sessionStorage.setItem('role-'+SYS,role);page='dashboard';tabs=[page];render()};document.querySelector('[data-act=password]').onclick=()=>overlay('修改密码','演示身份，不修改真实账户',`<div class="form-grid"><label class="full">新密码<input type="password" id="new-password" minlength="8"></label></div>`,btn('取消','close','close')+btn('保存','password-save','check',true));document.addEventListener('click',passwordHandler,{once:true});document.querySelector('[data-act=qr]').onclick=()=>overlay('二维码登录','演示入口',`<p>真实扫码认证需要身份服务。本原型可使用左侧演示账户完成登录。</p>`,btn('返回','close','back'));translate()}
function passwordHandler(e){if(e.target.closest('[data-act=password-save]')){if((document.getElementById('new-password')?.value.length||0)<8)return toast('密码至少 8 位');closeLayer();toast('演示密码修改完成')}else document.addEventListener('click',passwordHandler,{once:true})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.modal-back')?.remove();closeLayer()}if(e.key==='Tab'){const box=document.querySelector('.modal-back')||document.querySelector('.drawer')||document.querySelector('.menu-panel');if(box){const focus=[...box.querySelectorAll('button,input,select,textarea,a')].filter(e=>!e.disabled&&e.offsetParent!==null);let first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}});
